+import { OutputPass } from 'three/addons/postprocessing/OutputPass.js';
+import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js';
+
+function hasWebGL(){ try{ const c=document.createElement('canvas'); return !!(window.WebGLRenderingContext && (c.getContext('webgl2')||c.getContext('webgl'))); }catch(e){ return false; } }
+if(!hasWebGL()){ window.__acStarted=true; window.__acFail(); }
+else {
+  try { main(); } catch(err){ console.error(err); window.__acStarted=true; window.__acFail('The 3D scene failed to start on this device. Here is the explanation in text form.'); }
+}
+
+function main(){
+const reduced = matchMedia('(prefers-reduced-motion: reduce)').matches;
+const isSmall = Math.min(innerWidth, innerHeight) < 600;
+const V=(x,y,z)=>new THREE.Vector3(x,y,z);
+const UP=V(0,1,0), XAX=V(1,0,0);
+const lerp=THREE.MathUtils.lerp, clamp=THREE.MathUtils.clamp;
+const $=id=>document.getElementById(id);
+
+const state={ system:'split', mode:'cool', playing:true, labels:true, mix:0, simT:0, tIn:27.5 };
+
+/* ---------- renderer ---------- */
+const canvas=$('c');
+const renderer=new THREE.WebGLRenderer({canvas, antialias:true, powerPreference:'high-performance'});
+renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
+renderer.setSize(innerWidth, innerHeight, false);
+renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap;
+renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.0;
+renderer.localClippingEnabled=true;
+canvas.addEventListener('webglcontextlost', e=>{ e.preventDefault(); window.__acFail('The graphics context was lost. Reload the page to restart the 3D exhibit.'); });
+
+const labelRenderer=new CSS2DRenderer({element:$('labels')});
+labelRenderer.setSize(innerWidth, innerHeight);
+
+const scene=new THREE.Scene();
+scene.fog=new THREE.Fog(0x0b0f15, 16, 40);
+const camera=new THREE.PerspectiveCamera(34, innerWidth/innerHeight, 0.05, 120);
+
+const pmrem=new THREE.PMREMGenerator(renderer);
+scene.environment=pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
+scene.environmentIntensity=0.45;
+
+const composer=new EffectComposer(renderer);
