+$('btnTour').onclick=()=>{ if(!state.playing) togglePlay(); startTour(); };
+
+document.querySelectorAll('[data-system]').forEach(b=>b.onclick=()=>{ if(state.system===b.dataset.system) return; state.system=b.dataset.system; applyState(false); if(tut.tour){ tut.steps=tourSteps(); showStep(); } else startLive(); });
+document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{ if(state.mode===b.dataset.mode) return; state.mode=b.dataset.mode; applyState(true); if(tut.tour){ tut.steps=tourSteps(); showStep(); } else startLive(); });
