import { chromium } from 'playwright-core';
const exe = process.env.HOME + '/Library/Caches/ms-playwright/chromium-1208/chrome-mac-arm64/Google Chrome for Testing.app/Contents/MacOS/Google Chrome for Testing';
const browser = await chromium.launch({ executablePath: exe, args: ['--use-angle=metal', '--enable-gpu', '--ignore-gpu-blocklist'] });
const url = 'file://' + new URL('../index.html', import.meta.url).pathname;
for (const vp of [{ width: 1440, height: 900, name: 'desktop' }, { width: 390, height: 844, name: 'mobile', isMobile: true, hasTouch: true, deviceScaleFactor: 3 }]) {
  const ctx = await browser.newContext({ viewport: { width: vp.width, height: vp.height }, isMobile: !!vp.isMobile, hasTouch: !!vp.hasTouch, deviceScaleFactor: vp.deviceScaleFactor || 2 });
  const page = await ctx.newPage();
  const errs = [];
  page.on('pageerror', e => errs.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type() === 'error' || m.type() === 'warning') errs.push(m.type() + ': ' + m.text()); });
  await page.goto(url);
  await page.waitForFunction(() => window.__acStarted === true, null, { timeout: 30000 });
  await page.waitForTimeout(2500);
  const fallback = await page.$eval('#fallback', e => !e.hidden);
  const title = await page.title();
  const h1 = await page.$eval('header h1', e => e.textContent);
  await page.screenshot({ path: `shot-${vp.name}-1.png` });
  const tap = async sel => { if (vp.hasTouch) await page.tap(sel); else await page.click(sel); await page.waitForTimeout(400); };
  await tap('[data-mode="heat"]');
  await tap('[data-system="mono"]');
  await page.waitForTimeout(1500);
  const s1 = await page.evaluate(() => ({ ...window.__ac.state }));
