  const tourTag = await page.$eval('#capTag', e => e.textContent);
  await tap('#capNext'); const tourTag2 = await page.$eval('#capTag', e => e.textContent);
  await tap('#capPrev'); await tap('#capClose');
  const liveTag = await page.$eval('#capTag', e => e.textContent);
  await tap('#btnLabels'); const labelsOff = await page.$eval('#labels', e => e.classList.contains('off'));
  await tap('#btnLabels');
  let legend = 'n/a';
  if (await page.$eval('#btnLegend', e => getComputedStyle(e).display !== 'none')) { await tap('#btnLegend'); legend = await page.$eval('#legend', e => getComputedStyle(e).display); }
  await tap('[data-mode="cool"]'); await tap('[data-system="split"]');
  const s2 = await page.evaluate(() => ({ system: window.__ac.state.system, mode: window.__ac.state.mode }));
